// Custom material that sweeps color based on x-coordinate and time
material Sweep {
    param t: f32 = 0.0;

    fragment(input: SurfaceInput) -> color {
        // x ranges from -2 to 2 in object space (panel is 4 wide, centered)
        let x = input.position.x;
        let w = 0.5 + 0.5 * sin(0.8 * x + t);

        // Colors in sRGB
        let a_srgb = vec3(0x1a / 255.0, 0x23 / 255.0, 0x7e / 255.0);
        let b_srgb = vec3(0xff / 255.0, 0xb3 / 255.0, 0x00 / 255.0);

        // Convert to linear
        let a_linear = color.linear(a_srgb, 1.0).rgb;
        let b_linear = color.linear(b_srgb, 1.0).rgb;

        // Blend in linear space
        let blended = (1.0 - w) * a_linear + w * b_linear;

        // Return as linear (no sRGB conversion back, display as-is)
        return vec4(blended, 1.0);
    }
}

