// Custom material that sweeps color based on object-space x coordinate and time
material Sweep {
    param time: f32 = 0.0;

    fragment(input: SurfaceInput) -> color {
        // A and B colors in sRGB
        let color_a_srgb = vec3(0x1a / 255.0, 0x23 / 255.0, 0x7e / 255.0);
        let color_b_srgb = vec3(0xff / 255.0, 0xb3 / 255.0, 0x00 / 255.0);

        // Convert from sRGB to linear
        let color_a_linear = color.linear(color_a_srgb, 1.0).rgb;
        let color_b_linear = color.linear(color_b_srgb, 1.0).rgb;

        // Get x coordinate from surface input (in object space, runs from -2 to 2)
        let x = input.position.x;

        // Compute weight: w = 0.5 + 0.5 * sin(0.8 * x + t)
        let w = 0.5 + 0.5 * sin(0.8 * x + time);

        // Blend in linear space: (1 - w) * A + w * B
        let blended = (1.0 - w) * color_a_linear + w * color_b_linear;

        // Return as linear color (already in linear space)
        return color.linear(blended, 1.0);
    }
}

